import ""

export default function MyfirstComponent() {
  const x = 10;
  const person = {
    name: "Tarmeez",
    age: 20,
  };

  const elmStyle = {
    backgroundColor: "blue",
    color: "white",
    padding: "10px",
  };

  return (
    <div>
      <h1 style={elmStyle}>
        {person.name}
        {/* {sayhello()} */}
      </h1>

      <h2
        style={{
          backgroundColor: "red",
          color: "white",
          padding: "10px",
        }}
      >
        {x + 10} My First Component2
      </h2>

      <h3 style={elmStyle}>{10}My First Component2 x + 10</h3>
      <h4 className={"active id redBg"}>{person.age}</h4>
      <button onClick={sayhello}>click on</button>
    </div>
  );
}

function sayhello() {
  alert("Hello Tarmeez");
}

